import re, glob, os

tbl = {}
for line in open('draft/numerals.md'):
    m = re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|', line)
    if m and m.group(1).isdigit():
        tbl[int(m.group(1))] = m.group(2)
print("table", len(tbl), sorted(tbl))

def nums(t):
    return set(int(x) for x in re.findall(r'(?<![\d.])(\d{2})(?![\d.])', t))

used = set()
for f in sorted(glob.glob('draft/*.md')) + sorted(glob.glob('figures/*.md')):
    if f.endswith('numerals.md'):
        continue
    t = open(f).read()
    n = nums(t)
    used |= n
    bad = n - set(tbl)
    print(os.path.basename(f), sorted(n), "NOT_IN_TABLE:", sorted(bad) if bad else "-")
print("table entries never used:", sorted(set(tbl) - used))

